#!/usr/bin/env bash
# Copyright (c) 2026 Flisk Landscape contributors
# SPDX-License-Identifier: MIT
# Ground-truth evaluation for L1-L4 layer experiments. DO NOT EDIT during an autoresearch run.
# Re-vendors this engine into the ERP project, regenerates Dockerfiles through Tilt, rebuilds the
# golden layers and a fixed sample of 20 real ERP services, runs the container benchmark and the
# feature tests, then prints one summary block.
set -uo pipefail
CORE="$(cd "$(dirname "$0")/../.." && pwd)"
ERP="${TDK_BENCH_PROJECT:-$CORE/../tdk-erp-system}"
SAMPLE="${LAYER_EVAL_SAMPLE:-20}"
TDK_CLI="${TDK_CLI:-$CORE/cli/bin/tdk.js}"
PREFIX="$(python3 -c "import json;print(json.load(open('$ERP/.tdk/project.json'))['project']['name'])")"
t() { date +%s; }

cd "$ERP" || exit 1
TDK_EXTENSION_SOURCE="$CORE" node "$TDK_CLI" project --yes >/dev/null 2>&1 || { echo "status: crash (flisk project)"; exit 1; }
tilt alpha tiltfile-result -f .tdk/.tdk-out/Tiltfile >/dev/null 2>&1 || { echo "status: crash (Tiltfile evaluation)"; exit 1; }

s=$(t)
for target in l1_golden:l1 l2_golden:l2 l3_backend_golden:l3-backend l3_frontend_golden:l3-frontend l4_backend_bun:l4-backend l4_frontend_golden:l4-frontend; do
  docker build -q -f .tdk/.tdk-out/golden-layers.Dockerfile --target "${target%%:*}" -t "$PREFIX-${target##*:}:latest" . >/dev/null 2>&1 \
    || { echo "status: crash (golden ${target%%:*})"; exit 1; }
done
golden_build_s=$(( $(t) - s ))

s=$(t)
find services -mindepth 3 -maxdepth 3 -type f -name service.json | sort | head -n "$SAMPLE" | while read -r manifest; do
  dir="$(dirname "$manifest")"; svc="$(basename "$dir")"; stack="$(basename "$(dirname "$dir")")"
  echo "docker build -q -f $dir/.autogenerated/Dockerfile.app.autogenerated --target production -t ${stack}_${svc}:dev . >/dev/null 2>&1 || echo FAIL $svc"
done | xargs -P 4 -I{} sh -c '{}' | tee /tmp/layer-eval-build.log
grep -q FAIL /tmp/layer-eval-build.log && { echo "status: crash (service build: $(grep FAIL /tmp/layer-eval-build.log | head -3 | tr '\n' ' '))"; exit 1; }
service_build_s=$(( $(t) - s ))

cd "$CORE" || exit 1
marker="$(mktemp "${TMPDIR:-/tmp}/flisk-layer-eval.XXXXXX")" || { echo "status: crash (benchmark marker)"; exit 1; }
if ! bun scripts/benchmark/container-scale.ts --synthetic --tiers "$SAMPLE" --gate "$SAMPLE" --settle 15 > /tmp/layer-eval-bench.log 2>&1; then
  rm -f "$marker"
  echo "status: crash (container benchmark)"
  exit 1
fi
result="$(python3 - "$marker" <<'PY'
import glob, os, sys
marker_ns = os.stat(sys.argv[1]).st_mtime_ns
paths = [p for p in glob.glob("benchmarks/results/container-scale-*.json")
         if os.stat(p).st_mtime_ns > marker_ns]
if not paths:
    sys.exit(1)
print(max(paths, key=os.path.getmtime))
PY
)" || {
  rm -f "$marker"
  echo "status: crash (no fresh benchmark result)"
  exit 1
}
rm -f "$marker"
tests=pass
python3 -m pytest tests/tilt-engine/test_runtime_container_footprint.py -q -p no:cacheprovider >/tmp/layer-eval-tests.log 2>&1 || tests=fail

python3 - "$result" "$ERP" "$SAMPLE" "$PREFIX" "$golden_build_s" "$service_build_s" "$tests" <<'PY'
import json, subprocess, sys, glob, os
result, erp, sample, prefix, gb, sb, tests = sys.argv[1:]
r = json.load(open(result))["results"][0]
def size(img):
    out = subprocess.run(["docker", "image", "inspect", img, "--format", "{{.Size}}"], capture_output=True, text=True).stdout.strip()
    return int(out) / 1048576 if out else 0
base = size(f"{prefix}-l4-backend:latest")
svcs = sorted(glob.glob(f"{erp}/services/*/*/service.json"))[: int(sample)]
backend = [f"{os.path.basename(os.path.dirname(os.path.dirname(p)))}_{os.path.basename(os.path.dirname(p))}:dev" for p in svcs
           if json.load(open(p)).get("appType") != "frontend"]
sizes = [size(i) for i in backend]
ok = r["allHealthySeconds"] is not None and r["crashed"] == 0 and tests == "pass"
print("---")
print(f"mem_per_service_mib: {r['avgMemMiB']}")
print(f"service_image_mib:   {sum(sizes)/len(sizes):.1f}")
print(f"unique_per_service_mib: {sum(sizes)/len(sizes) - base:.1f}")
print(f"l4_backend_mib:      {base:.1f}")
print(f"all_healthy_s:       {r['allHealthySeconds']}")
print(f"crashed:             {r['crashed']}")
print(f"docker_ps_ms:        {r['dockerPsMs']}")
print(f"cpu_total_pct:       {r['totalCpuPct']}")
print(f"golden_build_s:      {gb}")
print(f"service_build_s:     {sb}")
print(f"tests:               {tests}")
print(f"status:              {'ok' if ok else 'invalid'}")
PY
